import time
from collections import deque

class RateLimiter:
    """
    A rate limiter that allows a maximum number of requests within a sliding time window.
    This implementation utilizes a deque for efficient timestamp management, ensuring O(1) time complexity 
    for both adding requests and removing expired timestamps.
    """

    def __init__(self, max_requests: int, window_seconds: float):
        if not isinstance(max_requests, int) or not isinstance(window_seconds, (int, float)):
            raise TypeError("max_requests must be an integer and window_seconds must be a positive number.")
        if max_requests < 1 or window_seconds <= 0:
            raise ValueError("max_requests must be at least 1 and window_seconds must be greater than 0.")

        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.timestamps = deque()

    def allow(self) -> bool:
        current_time = time.time()
        self._clean_expired_timestamps(current_time)

        if len(self.timestamps) < self.max_requests:
            self.timestamps.append(current_time)
            return True
        return False

    def _clean_expired_timestamps(self, current_time: float) -> None:
        while self.timestamps and self.timestamps[0] <= current_time - self.window_seconds:
            self.timestamps.popleft()
